-- 22. Modal verbs
with c as (select id from public.courses where name = $q$Kids (Prezident maktabi)$q$),
t as (
  insert into public.practice_topics (course_id, kind, unit, code, title, title_uz, sort_order, content)
  select c.id, 'grammar', 22, $q$KG22$q$, $q$22. Modal verbs$q$, $q$Modal fe’llar · 200 ta test$q$, 22, $q${"intro":{"what":"Modal fe’llar qobiliyat, ruxsat, majburiyat, ta’qiq, maslahat va ehtimolni bildiradi. Ulardan keyin fe’l doim ASL shaklda (to siz).","when":[],"structures":[],"rules":[],"signal_words":[],"topics":[{"name":"can, could","name_uz":"Qobiliyat va ruxsat","summary":"can — hozir qila olaman; could — o‘tmishda qila olardim. Ruxsat so‘rash: Can I …? / May I …?","usage":[{"text":"Hozirgi qobiliyat.","example":{"en":"I can swim.","uz":"Men suza olaman."}},{"text":"O‘tmishdagi qobiliyat.","example":{"en":"She could read when she was four.","uz":"U to‘rt yoshida o‘qiy olardi."}},{"text":"Ruxsat.","example":{"en":"Can I use your pen?","uz":"Ruchkangdan foydalansam maylimi?"}}],"structure":[{"type":"+","formula":"subject + can + verb","example":{"en":"He can play chess.","uz":"U shaxmat o‘ynay oladi."}},{"type":"-","formula":"subject + can’t / couldn’t + verb","example":{"en":"I can’t sing.","uz":"Men kuylay olmayman."}},{"type":"?","formula":"Can + subject + verb?","example":{"en":"Can you help me?","uz":"Yordam bera olasanmi?"}}],"signals":[],"tip":"“He cans”, “I can to swim” — XATO."},{"name":"must, mustn’t, have to, don’t have to","name_uz":"Majburiyat va ta’qiq","summary":"must / have to — kerak, shart. mustn’t — mumkin emas (ta’qiq). don’t have to — shart emas (xohlasang qil).","usage":[{"text":"must — qoida, majburiyat.","example":{"en":"You must wear a helmet.","uz":"Dubulg‘a kiyishing shart."}},{"text":"mustn’t — ta’qiq.","example":{"en":"You mustn’t smoke here.","uz":"Bu yerda chekish mumkin emas."}},{"text":"have to / has to — zarurat.","example":{"en":"She has to work on Saturdays.","uz":"U shanbalari ishlashi kerak."}},{"text":"don’t have to — shart emas.","example":{"en":"You don’t have to come.","uz":"Kelishing shart emas."}}],"structure":[],"signals":[],"tip":"mustn’t ≠ don’t have to! mustn’t — man etilgan; don’t have to — kerak emas."},{"na