-- 25. Both / Neither — All / None
with c as (select id from public.courses where name = $q$Kids (Prezident maktabi)$q$),
t as (
  insert into public.practice_topics (course_id, kind, unit, code, title, title_uz, sort_order, content)
  select c.id, 'grammar', 25, $q$KG25$q$, $q$25. Both / Neither — All / None$q$, $q$Ikkalasi / hech biri, hammasi / hech kim · 200 ta test$q$, 25, $q${"intro":{"what":"Ikki kishi / narsa haqida: both (ikkalasi ham), neither (hech biri), either (biri). Uch va undan ko‘p: all (hammasi), none (hech biri).","when":[],"structures":[],"rules":[],"signal_words":[],"topics":[{"name":"both, neither, either","name_uz":"Ikki narsa haqida","summary":"both — ikkalasi ham; neither — ikkalasi ham emas; either — u yoki bu. Juftlar: both … and, neither … nor, either … or.","usage":[{"text":"both","example":{"en":"Both Ali and Vali play chess.","uz":"Ali ham, Vali ham shaxmat o‘ynaydi."}},{"text":"neither","example":{"en":"Neither of my brothers smokes.","uz":"Akalarimning hech biri chekmaydi."}},{"text":"either","example":{"en":"You can sit on either chair.","uz":"Istalgan stulga o‘tirishing mumkin."}}],"structure":[{"type":"+","formula":"Both A and B + plural verb","example":{"en":"Both my parents are doctors.","uz":"Ota-onamning ikkalasi ham shifokor."}},{"type":"-","formula":"Neither A nor B + verb","example":{"en":"Neither Tom nor Jack likes fish.","uz":"Tom ham, Jek ham baliqni yoqtirmaydi."}}],"signals":[],"tip":"neither o‘zi inkor — fe’l inkor bo‘lmaydi: Neither of them knows (doesn’t know — XATO)."},{"name":"all, none","name_uz":"Ko‘pchilik haqida","summary":"all — hammasi (3+); none — hech biri (3+). of dan keyin obyekt olmoshi: all of us, none of them.","usage":[{"text":"all","example":{"en":"All of the students passed.","uz":"O‘quvchilarning hammasi o‘tdi."}},{"text":"none","example":{"en":"None of my friends came.","uz":"Do‘stlarimdan hech biri kelmadi."}}],"structure":[{"type":"+","formula":"all of / none of + us / you / them / the + noun","example":{"en":"None of us knew.","uz":"Hech birimiz bilmasdik."}}],"signals":[],"tip":"Ikki kishi → both / neither; uch va ko‘p → all / none."}],"mistakes":[{"wrong":"All my parents are teachers.","right":"Both my parents are teachers.","why":"Ikki kishi → both."},{"wrong":"Neither of them don’t know.","right":"Neither of them knows.","why":"Ikki inkor bo‘lmaydi."},{"wrong":"Both Ali or Vali …","right":"Both Ali and Vali …","why":"both … and."},{"wrong":"None of we …","right":"None of us …","why":"of + obyekt olmoshi."},{"wrong":"Neither of my three friends …","right":"None of my three friends …","why":"Uch kishi → none."}]},"parts":[],"translations":[],"test":[{"type":"mc","q":"You can ask ___ Tom or Jack. (qaysi biri bo‘lsa ham)","options":["either","both","neither","all"],"part":0},{"type":"mc","q":"You can ask ___ Timur or Javohir. (qaysi biri bo‘lsa ham)","options":["all","either","neither","both"],"part":0},{"type":"mc","q":"___ of them lives in Bukhara. (my grandma ham, my grandpa ham — hech biri)","options":["Either","Neither","None","Both"],"part":0},{"type":"mc","q":"You can ask ___ Olim or Rustam. (qaysi biri bo‘lsa ham)","options":["neither","either","both","all"],"part":0},{"type":"mc","q":"You can ask ___ Ali’s house or Vali’s house. (qaysi biri bo‘lsa ham)","options":["neither","both","either","all"],"part":0},{"type":"mc","q":"You can ask ___ my mum or my dad. (qaysi biri bo‘lsa ham)","options":["either","neither","all","both"],"part":0},{"type":"mc","q":"___ of them is difficult. (this test ham, that test ham — hech biri)","options":["Neither","Either","Both","None"],"part":0},{"type":"mc","q":"___ of them is a teacher. (Lola ham, Nodira ham — hech biri)","options":["Either","None","Neither","Both"],"part":0},{"type":"mc","q":"The cat and the dog are ___ hungry. (ikkalasi ham och)","options":["both","either","all","neither"],"part":0},{"type":"mc","q":"___ of them wants a dog. (my cousin ham, my friend ham — hech biri)","options":["Both","Either","None","Neither"],"part":0},{"type":"mc","q":"You can ask ___ the red dress or the blue dress. (qaysi biri bo‘lsa ham)","options":["all","either","neither","both"],"part":0},{"type":"mc","q":"My uncle and my aunt ___ drive a car. (ikkalasi ham mashina haydaydi)","options":["both","all","neither","either"],"part":0},{"type":"mc","q":"You can ask ___ Anvar or Bekzod. (qaysi biri bo‘lsa ham)","options":["neither","both","all","either"],"part":0},{"type":"mc","q":"___ of them speaks English. (Malika ham, Laylo ham — hech biri)","options":["Neither","Either","None","Both"],"part":0},{"type":"mc","q":"You can ask ___ my father or my uncle. (qaysi biri bo‘lsa ham)","options":["all","both","either","neither"],"part":0},{"type":"mc","q":"___ of them has got a bike. (Anvar ham, Bekzod ham — hech biri)","options":["Either","Neither","None","Both"],"part":0},{"type":"mc","q":"___ of them sings well. (Kamola ham, Zarina ham — hech biri)","options":["None","Either","Neither","Both"],"part":0},{"type":"mc","q":"___ of them draws well. (Shahzoda ham, Madina ham — hech biri)","options":["Both","None","Neither","Either"],"part":0},{"type":"mc","q":"Shahzoda and Madina ___ draw well. (ikkalasi ham yaxshi chizadi)","options":["either","neither","all","both"],"part":0},{"type":"mc","q":"You can ask ___ this test or that test. (qaysi biri bo‘lsa ham)","options":["neither","both","either","all"],"part":0},{"type":"mc","q":"The bus and the train are ___ fast. (ikkalasi ham tez)","options":["both","neither","all","either"],"part":0},{"type":"mc","q":"You can ask ___ Shahzoda or Madina. (qaysi biri bo‘lsa ham)","options":["both","either","all","neither"],"part":0},{"type":"mc","q":"My brother and my sister ___ go to school. (ikkalasi ham maktabga boradi)","options":["both","all","either","neither"],"part":0},{"type":"mc","q":"My father and my uncle ___ watch football. (ikkalasi ham futbol ko‘radi)","options":["both","neither","all","either"],"part":0},{"type":"mc","q":"___ of them can swim. (Sardor ham, Jasur ham — hech biri)","options":["Both","Either","Neither","None"],"part":0},{"type":"mc","q":"___ of them is hungry. (the cat ham, the dog ham — hech biri)","options":["Both","Neither","Either","None"],"part":0},{"type